/// is always all thirteen and would carry the first clip's values to every
/// other. An action's end decodes its `color` through this type too, so the
/// sub-tab's `◆N` sees exactly the keys an end holds.
struct ColorPatch: Codable, Equatable {
    var brightness: Double?
    var contrast: Double?
    var saturation: Double?
    var hue: Double?
    var exposure: Double?
    var temperature: Double?
    var tint: Double?
    var highlights: Double?
    var shadows: Double?
    var whites: Double?
    var blacks: Double?
    var vibrance: Double?
    var fade: Double?

    init(
        brightness: Double? = nil, contrast: Double? = nil, saturation: Double? = nil,
        hue: Double? = nil, exposure: Double? = nil, temperature: Double? = nil,
        tint: Double? = nil, highlights: Double? = nil, shadows: Double? = nil,
        whites: Double? = nil, blacks: Double? = nil, vibrance: Double? = nil,
        fade: Double? = nil
    ) {
        self.brightness = brightness
        self.contrast = contrast
        self.saturation = saturation
        self.hue = hue
        self.exposure = exposure
        self.temperature = temperature
        self.tint = tint
        self.highlights = highlights
        self.shadows = shadows
        self.whites = whites
        self.blacks = blacks
        self.vibrance = vibrance
        self.fade = fade
    }

    /// Every key, the whole group: what the canvas's eyedropper writes to
    /// neutralise a clip while it picks.
    init(_ whole: ColorAdjust) {
        self.init(
            brightness: whole.brightness, contrast: whole.contrast,
            saturation: whole.saturation, hue: whole.hue, exposure: whole.exposure,
            temperature: whole.temperature, tint: whole.tint, highlights: whole.highlights,
            shadows: whole.shadows, whites: whole.whites, blacks: whole.blacks,
            vibrance: whole.vibrance, fade: whole.fade)
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        brightness = c.lenient(.brightness)
        contrast = c.lenient(.contrast)
        saturation = c.lenient(.saturation)
        hue = c.lenient(.hue)
        exposure = c.lenient(.exposure)
        temperature = c.lenient(.temperature)
        tint = c.lenient(.tint)
        highlights = c.lenient(.highlights)
        shadows = c.lenient(.shadows)
        whites = c.lenient(.whites)
        blacks = c.lenient(.blacks)
        vibrance = c.lenient(.vibrance)
        fade = c.lenient(.fade)
    }

    /// The Color section's Reset: its four keys at 0, and nothing of Light's.
    static let neutralColor = ColorPatch(brightness: 0, contrast: 0, saturation: 0, hue: 0)

    /// The Light section's Reset: its nine keys at 0, and nothing of Color's.
    static let neutralLight = ColorPatch(
        exposure: 0, temperature: 0, tint: 0, highlights: 0, shadows: 0, whites: 0, blacks: 0,
        vibrance: 0, fade: 0)

    var isEmpty: Bool { self == ColorPatch() }
}

extension ColorAdjust {
    /// The Color section's four at 0 (its summary and its Reset's question).
import AppKit

/// The Clip tab: a pinned block — the selection header, the action lane and
/// the sub-tabs (spec §11 CI-5) — over the sections of the ACTIVE sub-tab.
///
/// **It owns almost no controls.** The rows are the ones the Video, Audio,
/// Text and Shape panes have always built, so this pane holds one instance of
/// each — never added to any view hierarchy — and uses them purely as section
/// factories. That is safe because a pane holds no state of its own: it reads
/// and writes through the shared `InspectorBinding` this inspector handed it,
/// and the sections it makes are plain `NSView`s that keep working wherever
/// they are added. What this file adds is the header, the Timing section, and
/// `makeSections()` — the function from the selection's kind and the active
/// sub-tab to the ordered list of sections.
///
/// **Why the sections are the ones that already existed.** The handoff's table
/// draws five groups (TRANSFORM · VIDEO · AUDIO · EFFECTS · TIMING) of four or
/// five rows each, but the same document says the pane contents move "into
/// sections largely as-is" and that the work is "the shell and the
/// kind-to-sections function, not the rows". Those two readings disagree, and
/// this is the one that loses nothing: today's twenty-odd sections each carry
/// their own Reset button and their own evaluated-action note ("Editing action
/// 2's end state"), both of which are per-section by construction
/// (`InspectorSection`), and folding five of them into one VIDEO group would
/// have to throw away four Resets and four notes. So the existing sections
/// stay the unit, the Clip tab lists them all, and the section SUMMARY the
/// design asks for — plus Transform open and the rest closed — is what keeps
/// the panel readable at that length.
final class ClipPane: InspectorPaneView {
    /// The five factories. Constructed once and kept: their sections capture
    /// them (a Reset closure holds `binding`, a button holds `inspector`), and
    /// they are cheap — an `NSView` with a stack view nobody ever lays out.
    let videoPane: VideoPane
    private let audioPane: AudioPane
    private let textPane: TextPane
    private let shapePane: ShapePane
    private let graphicPane: GraphicPane
    /// The sub-tab picked by hand, if any. Forgotten by the CONTROLLER when
    /// the selection's ids change (`forgetSubTab()`), never here.
    private var chosen: ClipSubTab?
    /// The sections the selected action keys, opened once per selection (CI-8).
    private let reveal = KeyedReveal()
    /// The Look section's gallery model (spec §11 GR-7 [b]), kept here rather
    /// than in the section so its thumbnails outlive a rebuild.
    let lookGallery = LookGallery()
    /// The Curves section's channel, selected point and unwritten list (spec
    /// §11 GR-12), kept here so they outlive a rebuild; per window, never saved.
    let curveState = CurveEditorState()
    /// The Background section's held Status (road map creator-jobs CO3, spec §11 CO-30 (d)),
    /// kept here so it outlives a rebuild; its ticker refreshes the pane when the state moves.
    let cutoutMemo = CutoutStatus.Memo()
    /// The Layout section's choices (road map creator-jobs CO7, spec §11 CO-71), per window.
    let layoutState = CameraLayoutSectionState()

    override init(inspector: InspectorViewController) {
        videoPane = VideoPane(inspector: inspector)
        audioPane = AudioPane(inspector: inspector)
        textPane = TextPane(inspector: inspector)
        shapePane = ShapePane(inspector: inspector)
        graphicPane = GraphicPane(inspector: inspector)
        super.init(inspector: inspector)
        cutoutMemo.onChange = { [weak self] in self?.refresh() }
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ClipPane does not support NSCoder")
    }

    // MARK: - Shape of the panel

    /// The four panes' signatures, composed. Each of them knows something this
    /// one cannot see — a filter added, a text family changed, a shape kind
    /// switched — and a signature that missed any of it would leave the pane
    /// refreshed but not rebuilt, which shows up as controls that never
    /// appear.
    ///
    /// The two halves are added on top of them all, because whether the
    /// selection has PIXELS and whether it has AUDIO each add or remove a
    /// whole group of sections while every clip id stays exactly as it was.
    /// The audio half is the one that moves under an edit: `hasAudio` reads
    /// `clip.enabled.audio`, so Detach Audio changes it, and so does the
    /// agent's `set_enabled` (§6), which no UI control sends. The video half does NOT track that flag —
    /// `hasPixels` asks the MEDIA whether it has a video track, not the clip
    /// whether its video is on — so what moves it is a relink or a consolidate
    /// that puts different media under the clip. Both are cheap to ask and
    /// neither is visible in the four panes' own signatures.
    override var structureSignature: String {
        [
            super.structureSignature,
            videoPane.structureSignature,
            textPane.structureSignature,
            shapePane.structureSignature,
            graphicPane.structureSignature,
            audioPane.structureSignature,
            (binding.videoClips.isEmpty ? "-" : "px") + (binding.audioClips.isEmpty ? "-" : "au"),
            activeSubTab.rawValue, subTabs.map(\.rawValue).joined(separator: ","),
            matteNote == nil ? "-" : "matte",
            // Whether every clip has a look adds or removes Look's Amount row.
            videoPane.allLooked ? "look" : "-",
            // Whether every clip can be cut out adds or removes Background (CO-30 (a)), and
            // whether every clip is a picture its Subject row (CO-108).
            videoPane.allCutoutable ? (videoPane.allPictures ? "cutout-image" : "cutout") : "-",
            // Whether the selection can be put behind a subject adds or removes Behind Subject
            // (CO-55).
            videoPane.allBehindable ? "behind" : "-",
            // Whether every media has a cursor not in the picture adds or removes Cursor (CU-38).
            videoPane.allCursored ? "cursor" : "-",
            // Hide While Silent and its "Speech from" list (CO-94).
            videoPane.allHideable ? "hide:" + HideSilentSources.candidates(
                for: binding.clips, in: binding.snapshot).map { "\($0.id)" }.joined(separator: ",")
                : "-",
            // A LUT look over a Camera Log file adds Look's warning row (GR-16).
            videoPane.lutOverCameraLog ? "twice" : "-",
            // A LUT look in an HLG project adds Look's other warning row (HD-13).
            videoPane.lutInHLG ? "hlg-lut" : "-",
            // The LUTs are the Look gallery's Imported tiles (GR-8 [b]).
            LookGallery.luts(in: binding.snapshot).map { "\($0.id)=\(LookGallery.lutName($0))" }
                .joined(separator: ","),
        ].joined(separator: "|")
    }

    override func makeHeader() -> (any OptionControl)? {
        let binding = self.binding
        let strip = ClipSubTabsView(
            tabs: subTabs, active: activeSubTab,
            badge: { [videoPane] tab in
                binding.selectedAction.map {
                    tab.keyedCount(in: $0.end, adjustment: videoPane.allAdjustment)
                } ?? 0
            },
            onSelect: { [weak inspector] in inspector?.selectClipSubTab($0) })
        return ClipHeaderBlock(
            binding: binding, inspector: inspector, subTabs: strip,
            note: matteNote == nil ? nil : { [weak self] in self?.matteNote })
    }

    // MARK: - Sub-tabs

    /// The selection's tabs, in display order: Text or Shape first for those
    /// kinds, Picture for clips that draw unless an adjustment clip is among
    /// them (spec §11 GR-6: it draws nothing of its own), Color when every
    /// one of those has source pixels or is an adjustment clip (GR-2, GR-6:
    /// never text, shape, graphic, nest or an audio-only file's clip, which
    /// draws nothing), Sound for clips with audio, and Clip always, last.
    var subTabs: [ClipSubTab] {
        var tabs: [ClipSubTab] = []
        if textPane.allText { tabs.append(.text) }
        if shapePane.allShape { tabs.append(.shape) }
        if graphicPane.allGraphic { tabs.append(.graphic) }
        if !binding.videoClips.isEmpty && !videoPane.anyAdjustment { tabs.append(.picture) }
        if !binding.videoClips.isEmpty && videoPane.allGradable { tabs.append(.color) }
        if !binding.audioClips.isEmpty { tabs.append(.sound) }
        tabs.append(.clip)
        return tabs
    }

    /// The tab picked by hand while the selection has it, else the first.
    var activeSubTab: ClipSubTab {
        let tabs = subTabs
        if let chosen, tabs.contains(chosen) { return chosen }
        return tabs.first ?? .clip
    }

    /// Records a pick; triggers nothing (`selectClipSubTab` refreshes).
    func choose(_ tab: ClipSubTab) { chosen = tab }

    /// Back to the default tab; triggers nothing. The controller calls it
    /// when the selection's ids change.
    func forgetSubTab() {
        chosen = nil
        curveState.clear()
    }

    // MARK: - Kind → sections

    /// The active sub-tab's sections, in the handoff's order. A section that
    /// does not apply is absent rather than disabled — the pane is rebuilt
    /// when the selection's kinds or the tab change, so there is nothing
    /// stale to grey out.
    ///
    /// Picture exists only for a selection with PIXELS: every control in it
    /// writes a `set_video` patch, and `InspectorBinding` addresses those to
    /// the clips that draw.
    override func makeSections() -> [InspectorSection] {
        let hasPixels = !binding.videoClips.isEmpty
        var sections: [InspectorSection] = []
        switch activeSubTab {
        case .text:
            sections = [
                textPane.contentSection(), textPane.fontSection(), textPane.styleSection(),
                textPane.outlineSection(), textPane.backdropSection(), textPane.boxSection(),
                textPane.animationSection(), textPane.presetSection(),
            ]
        case .shape:
            sections = [
                shapePane.shapeSection(), shapePane.strokeSection(), shapePane.fillSection(),
                // Immediately after Fill, because a gradient REPLACES a fill
                // when it is set and the two rows are read together.
                shapePane.gradientSection(), shapePane.arrowSection(),
            ]
        case .graphic:
            sections = [graphicPane.sourceSection()]
            if graphicPane.shared() != nil { sections.append(graphicPane.propertiesSection()) }
            sections.append(graphicPane.sizeSection())
            if binding.isSingle, let clip = binding.primary {
                sections.append(graphicPane.timelineSection(clip.id))
            }
        case .picture:
            sections = [videoPane.transformSection()]
            // Behind Subject right after Transform (road map creator-jobs CO5, CO-55).
            if videoPane.allBehindable { sections.append(videoPane.behindSubjectSection()) }
            // Layout after Behind Subject, before Crop (road map creator-jobs CO7, CO-71).
            if videoPane.allLayoutable { sections.append(videoPane.layoutSection(layoutState)) }
            if videoPane.allHideable { sections.append(videoPane.hideSilentSection()) }  // CO-94
            // `allSourcePixels` asks about the SOURCE KIND, so it says yes to
            // an audio-only file's clip too; the tab itself is what keeps a
            // crop off a clip that draws nothing.
            if videoPane.allSourcePixels {
                sections += [
                    videoPane.cropSection(), videoPane.cornerSection(), videoPane.chromaSection(),
                ]
                // Background right after Chroma Key (road map creator-jobs CO3, CO-30 (a)).
                if videoPane.allCutoutable { sections.append(videoPane.cutoutSection(cutoutMemo)) }
            }
            // Cursor after Background, before Shadow (road map creator-jobs CU3b, CU-38 (b)).
            if videoPane.allCursored { sections.append(videoPane.cursorSection()) }
            // Shadow is shared by all three drawing kinds, so it is here once.
            sections += [
                inspectorShadowSection(binding), videoPane.filtersSection(),
                videoPane.reflectionSection(), videoPane.spotlightSection(),
                videoPane.obscureSection(),
            ]
        case .color:
            // Light, then the Color section Picture used to hold (GR-2), then
            // Wheels (GR-11), Curves (GR-12), then Look (GR-7); Adjustment's
            // Strength first and the Qualifier second when every clip is an
            // adjustment clip (GR-6, GR-13).
            sections = [
                videoPane.lightSection(), videoPane.colorSection(), videoPane.wheelsSection(),
                videoPane.curvesSection(curveState),
            ]
            if videoPane.allAdjustment { sections.insert(videoPane.adjustmentSection(), at: 0) }
            if videoPane.allAdjustment { sections.insert(videoPane.qualifierSection(), at: 1) }
            sections.append(videoPane.lookSection(lookGallery))
        case .sound:
            sections = [
                audioPane.volumeSection(), audioPane.fadeSection(), audioPane.duckSection(),
                // The chain's head, in signal order (spec §11 AU-54, AU-38).
                audioPane.isolationSection(), audioPane.voiceSection(),
                audioPane.channelsSection(),
                audioPane.eqSection(), audioPane.humSection(),
                audioPane.noiseSection(), audioPane.gateSection(), audioPane.levellerSection(),
                audioPane.deEsserSection(),
                audioPane.compressorSection(), audioPane.mixSection(),
                // Last in the clip's chain, so last here (spec §11 AU-26).
                audioPane.limiterSection(),
            ]
        case .clip:
            if binding.isSingle, let clip = binding.primary {
                sections.append(timingSection(clip.id))
            } else if videoPane.allMedia {
                // The half of Timing a MULTI-clip selection can still answer
                // for: Reverse is a per-clip op that fans out happily, where
                // In, Out and Duration genuinely need one clip.
                sections.append(reverseTimingSection())
            }
            if videoPane.allMedia {
                sections.append(videoPane.speedSection())
            }
            if binding.isSingle, let clip = binding.primary,
               videoPane.overlap(before: clip) != nil {
                sections.append(videoPane.transitionSection(clip.id))
            }
            if hasPixels {
                sections.append(videoPane.motionSection())
            }
        }
        // A tab that would open as a column of shut headers opens its first
        // section with no stored preference instead. `expandByDefault` defers
        // to a section the user has closed themselves, so this is a default
        // and not an override — and it is offered to each section in TURN
        // because an id can be shared (`video.speed`, `clip.timing`), and a
        // group closed once elsewhere would otherwise leave the tab shut.
        if !sections.contains(where: { $0.isExpanded }) {
            for section in sections {
                if section.expandByDefault() { break }
            }
        }
        reveal.apply(sections, action: binding.selectedAction?.id, subTab: activeSubTab.rawValue)
        return sections
    }
}

    /// The Color section's four at 0 (its summary and its Reset's question).
    var isColorNeutral: Bool { brightness == 0 && contrast == 0 && saturation == 0 && hue == 0 }

    /// The Light section's nine at 0 — the tone keys `toneEnabled` reads.
    var isLightNeutral: Bool {
        exposure == 0 && temperature == 0 && tint == 0 && highlights == 0 && shadows == 0
            && whites == 0 && blacks == 0 && vibrance == 0 && fade == 0
    }
}

extension LayerUniforms {
    /// Tone's twelve floats (spec §11 GR-2): the nine in the model's order,
    /// and `toneEnabled` 1 exactly when one of them is not 0 — a negative
    /// value enables it as surely as a positive one. An untoned layer leaves
    /// the flag at 0 and never enters step 4c, so it renders byte-identical.
    mutating func apply(tone color: ColorAdjust) {
        let values = [
            color.exposure, color.temperature, color.tint, color.highlights, color.shadows,
            color.whites, color.blacks, color.vibrance, color.fade,
        ]
        exposure = Float(color.exposure)
        temperature = Float(color.temperature)
        tint = Float(color.tint)
        highlights = Float(color.highlights)
        shadows = Float(color.shadows)
        whites = Float(color.whites)
        blacks = Float(color.blacks)
        vibrance = Float(color.vibrance)
        fade = Float(color.fade)
        toneEnabled = values.contains { $0 != 0 } ? 1 : 0
    }
}

// MARK: - The wheels (spec §11 GR-11, grading-2 G2-2)

/// One wheel: the puck (`x`, `y`, inside the unit circle — its angle the hue,
/// 0° red, its distance the strength) and `master`, each −1…1, 0 neutral.
/// `model_grade.rs`'s `Wheel`, read leniently, each key absent at 0.
struct ColorWheel: Codable, Hashable {
    let x: Double
    let y: Double
    let master: Double

    init(x: Double = 0, y: Double = 0, master: Double = 0) {
        self.x = x
        self.y = y
        self.master = master
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        x = c.lenient(.x, 0)
        y = c.lenient(.y, 0)
        master = c.lenient(.master, 0)
    }

    static let neutral = ColorWheel()
    var isNeutral: Bool { self == .neutral }
}

/// `video.wheels`: lift, gamma and gain, in the model's order everywhere.
struct ColorWheels: Codable, Hashable {
    let lift: ColorWheel
    let gamma: ColorWheel
    let gain: ColorWheel

    init(lift: ColorWheel = .neutral, gamma: ColorWheel = .neutral, gain: ColorWheel = .neutral) {
        self.lift = lift
        self.gamma = gamma
        self.gain = gain
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        lift = c.lenient(.lift, ColorWheel.neutral)
        gamma = c.lenient(.gamma, ColorWheel.neutral)
        gain = c.lenient(.gain, ColorWheel.neutral)
    }

    static let neutral = ColorWheels()
    var isNeutral: Bool { self == .neutral }
}

/// What a wheel write SENDS: any of a wheel's three keys, each nil when the
/// write does not name it. A puck sends only `x, y`, a strip or a field only
/// `master`, so a write over several clips keeps each one's other values.
struct ColorWheelPatch: Codable, Equatable {
    var x: Double?
    var y: Double?
    var master: Double?

    init(x: Double? = nil, y: Double? = nil, master: Double? = nil) {
        self.x = x
        self.y = y
        self.master = master
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        x = c.lenient(.x)
        y = c.lenient(.y)
        master = c.lenient(.master)
    }

    var isEmpty: Bool { self == ColorWheelPatch() }
}

/// A sparse `wheels` write: the wheels it names, each sparse in turn. An
/// action's end decodes its `wheels` through this type too, so the sub-tab's
/// `◆N` sees exactly the keys an end holds.
struct ColorWheelsPatch: Codable, Equatable {
    var lift: ColorWheelPatch?
    var gamma: ColorWheelPatch?
    var gain: ColorWheelPatch?

    init(lift: ColorWheelPatch? = nil, gamma: ColorWheelPatch? = nil, gain: ColorWheelPatch? = nil) {
        self.lift = lift
        self.gamma = gamma
        self.gain = gain
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        lift = c.lenient(.lift)
        gamma = c.lenient(.gamma)
        gain = c.lenient(.gain)
    }

    /// The Wheels section's Reset: all nine at 0.
    static let neutral = ColorWheelsPatch(
        lift: ColorWheelPatch(x: 0, y: 0, master: 0),
        gamma: ColorWheelPatch(x: 0, y: 0, master: 0),
        gain: ColorWheelPatch(x: 0, y: 0, master: 0))

    var isEmpty: Bool {
        (lift?.isEmpty ?? true) && (gamma?.isEmpty ?? true) && (gain?.isEmpty ?? true)
    }
}

/// The three wheels as the Wheels section's columns: each one's title (its
/// undo name), its value in a `ColorWheels` and a patch naming it alone.
enum ColorWheelKind: CaseIterable {
    case lift, gamma, gain

    var title: String {
        switch self {
        case .lift: return "Lift"
        case .gamma: return "Gamma"
        case .gain: return "Gain"
        }
    }

    func wheel(_ wheels: ColorWheels) -> ColorWheel {
        switch self {
        case .lift: return wheels.lift
        case .gamma: return wheels.gamma
        case .gain: return wheels.gain
        }
    }

    func patch(_ wheel: ColorWheelPatch) -> ColorWheelsPatch {
        switch self {
        case .lift: return ColorWheelsPatch(lift: wheel)
        case .gamma: return ColorWheelsPatch(gamma: wheel)
        case .gain: return ColorWheelsPatch(gain: wheel)
        }
    }
}

