                                        texture3d<float> look [[texture(2)]],
                                        texture2d<float> curves [[texture(3)]],
                                        sampler samp [[sampler(0)]]) {
    float a = saturate(dst.a);
    float3 c = saturate(dst.rgb / max(a, 1e-4));
    bool linear = u.linearLight > 0.5;
    if (linear) {
